CREATE TABLE   if not exists User
(
    ID          		VARCHAR(50) 
    PRACTICE_ID			INTEGER												NOT NULL,
    EMAIL       		VARCHAR(250) 										UNIQUE NOT NULL,
    DISPLAY_NAME 		VARCHAR(250) 										NOT NULL,
    IS_ACTIVE		    integer	 											NOT NULL,
    CREATED_BY			VARCHAR(50) 										,
    CREATED_DATE		TIMESTAMP(6) 	DEFAULT		CURRENT_TIMESTAMP	    NOT NULL,
    UPDATED_BY			VARCHAR(50)										,
    UPDATED_DATE		TIMESTAMP(6)	DEFAULT		CURRENT_TIMESTAMP		NOT NULL					,
    CONSTRAINT USERS_PK PRIMARY KEY (ID)
);


CREATE TABLE ROLE (
    				  ID					VARCHAR(50)	 NOT NULL,
                      NAME		    VARCHAR(50)	  NOT NULL,
                      LABEL   VARCHAR(250)  NOT NULL,
                      ROLE_TYPE           VARCHAR(50)	 							      NOT NULL,
                      IS_ACTIVE		       integer	 							      NOT NULL,
                      CREATED_BY			VARCHAR(50) 										,
                      CREATED_DATE		TIMESTAMP(6) 	DEFAULT		CURRENT_TIMESTAMP	    NOT NULL,
                      UPDATED_BY			VARCHAR(50)										,
                      UPDATED_DATE		TIMESTAMP(6)	DEFAULT		CURRENT_TIMESTAMP		NOT NULL					,
                      CONSTRAINT ROLE_PK PRIMARY KEY (ID)
);


CREATE TABLE USER_ROLE (
                           ID					   VARCHAR(50)									  NOT NULL,
                           USER_ID		           VARCHAR(50)								      NOT NULL,
                           ROLE_ID                VARCHAR(50)									  NOT NULL,
                           IS_ACTIVE		       integer	 							      NOT NULL,
                           CREATED_BY			   VARCHAR(50) 										,
                           CREATED_DATE		   TIMESTAMP(6) 	DEFAULT		CURRENT_TIMESTAMP NOT NULL,
                           UPDATED_BY			   VARCHAR(50)										,
                           UPDATED_DATE		   TIMESTAMP(6)	DEFAULT		CURRENT_TIMESTAMP	  NOT NULL					,
                           CONSTRAINT USER_ROLE_PK PRIMARY KEY (ID),
                           CONSTRAINT USER_ROLE_FK1 FOREIGN KEY (ROLE_ID)
                               REFERENCES ROLE (ID) MATCH SIMPLE
                               ON UPDATE NO ACTION ON DELETE NO ACTION
);


CREATE TABLE PERMISSION (
                            ID					   VARCHAR(50)									  NOT NULL,
                            NAME		           VARCHAR(50)								      NOT NULL,
                            LABEL   VARCHAR(250)  NOT NULL,
                            IS_ACTIVE		       integer	 							      NOT NULL,
                            CREATED_BY			   VARCHAR(50) 										,
                            CREATED_DATE		   TIMESTAMP(6) DEFAULT		CURRENT_TIMESTAMP    NOT NULL,
                            UPDATED_BY			   VARCHAR(50)										,
                            UPDATED_DATE		   TIMESTAMP(6)	DEFAULT		CURRENT_TIMESTAMP	  NOT NULL					,
                            CONSTRAINT PERMISSION_PK PRIMARY KEY (ID)

);

CREATE TABLE ROLE_PERMISSION_MPNG (
                                      ID					   VARCHAR(50)									  NOT NULL,
                                      ROLE_ID		           VARCHAR(50)								      NOT NULL,
                                      PERMISSION_ID		   VARCHAR(50)	 							      NOT NULL,
                                      IS_ACTIVE		       integer	 							      NOT NULL,
                                      CREATED_BY			   VARCHAR(50) 										,
                                      CREATED_DATE		   TIMESTAMP(6) DEFAULT		CURRENT_TIMESTAMP    NOT NULL,
                                      UPDATED_BY			   VARCHAR(50)										,
                                      UPDATED_DATE		   TIMESTAMP(6)	DEFAULT		CURRENT_TIMESTAMP	  NOT NULL					,
                                      CONSTRAINT ROLE_PERMISSION_MPNG_PK PRIMARY KEY (ID),
                                      CONSTRAINT ROLE_PERMISSION_MPNG_FK1 FOREIGN KEY (ROLE_ID)
                                          REFERENCES ROLE (ID) MATCH SIMPLE,
                                      CONSTRAINT ROLE_PERMISSION_MPNG_FK2 FOREIGN KEY (PERMISSION_ID)
                                          REFERENCES PERMISSION (ID) MATCH SIMPLE
                                          ON UPDATE NO ACTION ON DELETE NO ACTION

);

COMMIT;
COMMIT;
COMMIT;